mapper.select:
SELECT proc.product_code , proc.name AS product_name , wrhs.warehouse_code , wrhs.name AS warehouse_name , ores.result_qty , ores.result_date FROM outbound_results AS ores JOIN outbound_schedules AS osch ON ores.company_id = osch.company_id AND ores.outbound_schedule_id = osch.outbound_schedule_id JOIN inventories AS invt ON osch.company_id = invt.company_id AND osch.inventory_id = invt.inventory_id JOIN products AS proc ON invt.company_id = proc.company_id AND invt.product_id = proc.product_id JOIN warehouses AS wrhs ON invt.company_id = wrhs.company_id AND invt.warehouse_id = wrhs.warehouse_id WHERE ores.company_id = #{companyId}
AND proc.product_code LIKE CONCAT('%', #{productCode}, '%')
AND proc.name LIKE CONCAT('%', #{productName}, '%')
AND wrhs.warehouse_code LIKE CONCAT('%', #{warehouseCode}, '%')
AND wrhs.name LIKE CONCAT('%', #{warehouseName}, '%')
AND ores.result_date >= #{resultDateFrom}
AND ores.result_date <= #{resultDateTo}
ORDER BY ores.outbound_result_id;
